-- EXPLAIN ANALYZE counts each partition's scan under its Append: the rows
-- it returned and its filter removed, and a partition the plan never
-- reached because a LIMIT stopped (never executed).
CREATE TABLE ml603 (a int, b int, c text) PARTITION BY RANGE (a);
CREATE TABLE ml603_1 PARTITION OF ml603 FOR VALUES FROM (0) TO (10) PARTITION BY LIST (b);
CREATE TABLE ml603_1a PARTITION OF ml603_1 FOR VALUES IN (1, 2);
CREATE TABLE ml603_1b PARTITION OF ml603_1 FOR VALUES IN (3);
CREATE TABLE ml603_1d PARTITION OF ml603_1 DEFAULT;
CREATE TABLE ml603_2 PARTITION OF ml603 FOR VALUES FROM (10) TO (20);
CREATE TABLE ml603_d PARTITION OF ml603 DEFAULT;
INSERT INTO ml603 VALUES (1, 1, 'a'), (5, 3, 'b'), (7, 9, 'c'), (15, 0, 'd'), (30, 0, 'e'), (2, 2, 'f');
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM ml603;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM ml603 WHERE c = 'b';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM ml603 WHERE a < 10 AND c > 'a';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM ml603 WHERE a = 5 AND b = 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM ml603 WHERE a = 500;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT count(*) FROM ml603;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM ml603 LIMIT 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT YAML) SELECT * FROM ml603 WHERE a < 9;
SELECT * FROM ml603 WHERE a = 5 AND b = 3;
SELECT a, c FROM ml603 WHERE a < 10 ORDER BY a;
